template<class T> std::vector<T> circuit_4(const std::vector<T>&q,const std::vector<T>&f){
 std::vector<T> b(4),v(4);
 b[0]=q[1]*T(0.5);
 b[1]=q[2]*T(0.5);
 b[2]=q[3]*T(0.5);
 b[3]=q[0]*T(0.5);
 T r=f[3],p=-b[3];
 r=f[2]-b[2]*r; p=-b[2]*p;
 r=f[1]-b[1]*r; p=-b[1]*p;
 r=f[0]-b[0]*r; p=-b[0]*p;
 v[0]=r/(T(1)-p);
 v[3]=f[3]-b[3]*v[0];
 v[2]=f[2]-b[2]*v[3];
 v[1]=f[1]-b[1]*v[2];
 return v;
}
